// ---- provenance phrases used in unit status lines ---------------------------------------------------------------
const XP_US = 'xp 1 (green): game rule for Grant\'s and Buell\'s volunteer formations at Shiloh other than the Fort Donelson division; no unit-level service history was researched';
const XP_DONELSON = 'xp 2 (trained): game rule for W. H. L. Wallace\'s 2nd Division, the Fort Donelson division; regiment-level Donelson service was not checked';
const XP_REGULAR = 'xp 2 (trained): game rule for a Regular Army battery';
const XP_CS = 'xp 1 (green): game default; no Confederate formation\'s earlier service was researched for this pack';
const WPN_CS = 'weapon smooth: Staff Ride Handbook p.16-17 and Daniel say most Confederates carried obsolete smoothbores and converted flintlocks (about 4,000 Enfields army-wide); no brigade return found';
const WPN_US_DEFAULT = 'weapon: no arms return found; a low-confidence default (the Handbook p.16 says Union men carried either the .69 M1841 rifled musket or the M1842 smoothbore)';
const POS = (why) => `position Inferred: ${why}`;
const status = (...parts) => parts.join('; ') + '.';

